#!/usr/bin/env node
/**
 * Daily briefing generator.
 *
 *   Reads:  data/news.json, data/sbir.json, data/funding.json, data/briefing.json (existing)
 *   Writes: data/briefing.json (fresh)
 *
 * Stats are computed deterministically from the data files. The editorial
 * narrative (headline, deck, stories, watchlist, tickers) is generated by
 * the LLM (GitHub Models or Anthropic). The talent block is held static —
 * it's EVONA's internal data, not something the LLM should infer.
 *
 * Fails safely: if the LLM call breaks, the existing briefing.json is
 * left untouched and the workflow exits clean.
 */

import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT      = path.resolve(__dirname, "..");

const NEWS_PATH     = path.join(ROOT, "data", "news.json");
const SBIR_PATH     = path.join(ROOT, "data", "sbir.json");
const FUNDING_PATH  = path.join(ROOT, "data", "funding.json");
const BRIEFING_PATH = path.join(ROOT, "data", "briefing.json");

const ANTHROPIC_API_KEY = process.env.ANTHROPIC_API_KEY || "";
const GH_MODELS_TOKEN   = process.env.GH_MODELS_TOKEN   || "";
const MODEL             = process.env.MODEL             || (ANTHROPIC_API_KEY ? "claude-haiku-4-5-20251001" : "openai/gpt-4o-mini");

/* ---------- LLM helpers (mirrors fetch-news.mjs) ---------- */
async function callAnthropic(prompt, maxTokens) {
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "x-api-key":         ANTHROPIC_API_KEY,
      "anthropic-version": "2023-06-01",
      "content-type":      "application/json"
    },
    body: JSON.stringify({
      model:      MODEL,
      max_tokens: maxTokens,
      messages:   [{ role: "user", content: prompt }]
    })
  });
  if (!res.ok) throw new Error(`Anthropic ${res.status}: ${(await res.text()).slice(0, 200)}`);
  const json = await res.json();
  return (json.content || []).find(c => c.type === "text")?.text || "";
}

async function callGitHubModels(prompt, maxTokens) {
  const endpoints = [
    "https://models.github.ai/inference/chat/completions",
    "https://models.inference.ai.azure.com/chat/completions"
  ];
  let lastErr;
  for (const url of endpoints) {
    try {
      const res = await fetch(url, {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${GH_MODELS_TOKEN}`,
          "Content-Type":  "application/json"
        },
        body: JSON.stringify({
          model:       MODEL,
          messages:    [{ role: "user", content: prompt }],
          max_tokens:  maxTokens,
          temperature: 0.5
        })
      });
      if (!res.ok) {
        lastErr = new Error(`GitHub Models ${res.status} at ${url.replace(/^https?:\/\//, "")}: ${(await res.text()).slice(0, 200)}`);
        continue;
      }
      const json = await res.json();
      return (json.choices?.[0]?.message?.content || "").trim();
    } catch (e) { lastErr = e; }
  }
  throw lastErr || new Error("GitHub Models: all endpoints failed");
}

async function callLLM(prompt, maxTokens) {
  if (ANTHROPIC_API_KEY) return callAnthropic(prompt, maxTokens);
  if (GH_MODELS_TOKEN)   return callGitHubModels(prompt, maxTokens);
  return "";
}

function extractJSON(text) {
  if (!text) return null;
  let cleaned = text.replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/, "").trim();
  try { return JSON.parse(cleaned); } catch (_) {}
  const firstObj = cleaned.indexOf("{");
  const firstArr = cleaned.indexOf("[");
  const start = Math.min(...[firstArr, firstObj].filter(i => i >= 0));
  if (!isFinite(start)) return null;
  const open = cleaned[start];
  const close = open === "[" ? "]" : "}";
  const end = cleaned.lastIndexOf(close);
  if (end <= start) return null;
  try { return JSON.parse(cleaned.slice(start, end + 1)); }
  catch (_) { return null; }
}

/* ---------- Stats: computed deterministically from data ---------- */
function fmtUSDm(amtMillions) {
  if (amtMillions >= 1000) return `$${(amtMillions / 1000).toFixed(1)}B`;
  if (amtMillions >= 1)    return `$${Math.round(amtMillions)}M`;
  return `$${(amtMillions * 1000).toFixed(0)}K`;
}

function computeStats(news, sbir, funding) {
  // Funding rounds in the last 7 days
  const last7Funding = (funding.rounds || []).filter(r => (r.daysAgo ?? 999) <= 7);
  const cap7d        = last7Funding.reduce((s, r) => s + (r.amt || 0), 0);
  const biggest      = last7Funding.length ? Math.max(...last7Funding.map(r => r.amt || 0)) : 0;
  const biggestCo    = last7Funding.find(r => r.amt === biggest)?.co || "—";

  // SBIR Phase II in the last 7 days (using awardDate)
  const today  = new Date();
  const cutoff = new Date(today); cutoff.setUTCDate(cutoff.getUTCDate() - 7);
  const cutoffISO   = cutoff.toISOString().slice(0, 10);
  const sbirThisWk  = (sbir.awards || []).filter(a => (a.awardDate || "") >= cutoffISO);
  const sbirAmt     = sbirThisWk.reduce((s, a) => s + (a.amt || 0), 0);

  const newsCount = (news.articles || []).length;

  return [
    { label: "Capital deployed",  value: fmtUSDm(cap7d),    sub: `rolling 7 days · ${last7Funding.length} rounds`, trend: "up"   },
    { label: "Biggest cheque",    value: fmtUSDm(biggest),  sub: `${biggestCo}, this week`,                        trend: "flat" },
    { label: "SBIR Phase II",     value: fmtUSDm(sbirAmt),  sub: `this week · ${sbirThisWk.length} winners`,        trend: "up"   },
    { label: "News tracked",      value: String(newsCount), sub: "across 13 sources",                              trend: "flat" },
    { label: "Defense primes",    value: "+",               sub: "still outpacing pure-plays",                     trend: "up"   },
    { label: "Resumes in motion", value: "+38%",            sub: "WoW, primes → Series B/C",                       trend: "up"   }
  ];
}

/* ---------- Editorial narrative via LLM ---------- */
async function generateNarrative(news, sbir, funding) {
  const headlines = (news.articles || []).slice(0, 30)
    .map(a => `• [${a.sourceId}] ${a.title} — ${(a.summary || "").slice(0, 200)}`)
    .join("\n");

  const recentFunding = (funding.rounds || []).filter(r => r.daysAgo <= 14).slice(0, 12);
  const fundingBlock = recentFunding.length
    ? recentFunding.map(r => `${r.co}: $${r.amt}M ${r.stage} (${r.sector}, T-${r.daysAgo}d) — ${r.desc}`).join("\n")
    : "(no disclosed rounds this period)";

  const sbirRecent = (sbir.awards || []).slice(0, 12);
  const sbirBlock  = sbirRecent.length
    ? sbirRecent.map(a => `${a.co} (${a.loc}): $${a.amt}M ${a.agency} — ${a.title}`).join("\n")
    : "(no SBIR awards in window)";

  const prompt = `You are an industry analyst writing the weekly intelligence briefing for "Space Intel by EVONA," a Bloomberg-style space industry terminal. Audience: aerospace engineers, founders, defense procurement leads, VCs investing in space.

VOICE: dry, slightly witty, never corporate. Think Matt Levine on aerospace, or Stratechery's voice. Specific numbers and names. No hype words ("transformative", "groundbreaking", "exciting", "innovative", "revolutionary"). Each story should land one sharp observation an analyst would say privately.

Write the briefing in EXACTLY this JSON shape:

{
  "headline": "3-7 word punchy headline as a complete sentence or three short clauses (example: 'Capital pivots. Procurement shifts. Talent walks.')",
  "deck": "1-2 sentence subhead summarising the week's signal",
  "stories": [
    {
      "kicker": "1-WORD CATEGORY IN CAPS",
      "head": "6-10 word story title with editorial punch",
      "body": "3-4 sentence story body grounded in specific names and dollar amounts from the data below",
      "soWhat": "1-2 sentence 'so what' — the editorial take, not the news recap"
    }
  ],
  "watchlist": [
    {
      "title": "5-8 word forward-looking item",
      "body": "1-2 sentence reason this matters next week"
    }
  ],
  "tickers": [
    { "sym": "TICKER or TICKER/TICKER", "note": "1 sentence punchy note about this ticker this week, referencing news where possible" }
  ]
}

EXACTLY 3 stories. EXACTLY 4 watchlist items. EXACTLY 4 ticker callouts.

Reference real companies and dollar amounts from the data. The "soWhat" should be the part you'd say off the record. Avoid the word "exciting." Avoid em-dash overuse. Avoid "in this rapidly evolving landscape."

DATA:

NEWS HEADLINES (last week, by source):
${headlines}

FUNDING ROUNDS (last 14 days):
${fundingBlock}

SBIR PHASE II AWARDS (recent):
${sbirBlock}

Return ONLY the JSON. No prose before or after. No markdown fences.`;

  const text   = await callLLM(prompt, 3000);
  const parsed = extractJSON(text);
  if (!parsed || !parsed.headline || !Array.isArray(parsed.stories) || parsed.stories.length === 0) {
    throw new Error(`LLM returned invalid briefing (first 200 chars: ${text.slice(0, 200)})`);
  }
  // Ensure we have the right counts; pad/trim if the model misbehaved
  parsed.stories   = (parsed.stories   || []).slice(0, 3);
  parsed.watchlist = (parsed.watchlist || []).slice(0, 4);
  parsed.tickers   = (parsed.tickers   || []).slice(0, 4);
  return parsed;
}

/* ---------- Issue numbering ---------- */
function nextIssueNumber(existing) {
  // Read prior "No. <n>" and increment if the date has changed
  const todayISO = new Date().toISOString().slice(0, 10);
  if (existing && existing.issue) {
    const m = String(existing.issue).match(/No\. (\d+)/);
    if (m) {
      const prevNum = parseInt(m[1], 10);
      // Don't increment twice in one day
      if (existing.updated === todayISO) return existing.issue;
      return `No. ${prevNum + 1}`;
    }
  }
  // Default seed if no prior issue
  return "No. 1";
}

/* ---------- Main ---------- */
async function main() {
  if (!ANTHROPIC_API_KEY && !GH_MODELS_TOKEN) {
    console.warn("No LLM configured (ANTHROPIC_API_KEY / GH_MODELS_TOKEN) — skipping briefing generation");
    return;
  }

  let news, sbir, funding, existing;
  try { news     = JSON.parse(await fs.readFile(NEWS_PATH,    "utf8")); }
  catch (e) { console.warn(`Could not read news.json: ${e.message}`); return; }
  try { sbir     = JSON.parse(await fs.readFile(SBIR_PATH,    "utf8")); }
  catch (e) { sbir = { awards: [] }; }
  try { funding  = JSON.parse(await fs.readFile(FUNDING_PATH, "utf8")); }
  catch (e) { funding = { rounds: [] }; }
  try { existing = JSON.parse(await fs.readFile(BRIEFING_PATH,"utf8")); }
  catch (e) { existing = {}; }

  let narrative;
  try {
    console.log(`Generating briefing narrative with ${ANTHROPIC_API_KEY ? "Anthropic" : "GitHub Models"} (${MODEL})…`);
    narrative = await generateNarrative(news, sbir, funding);
  } catch (e) {
    console.warn(`Briefing generation failed: ${e.message}`);
    console.warn("Existing data/briefing.json left untouched.");
    return;
  }

  const stats = computeStats(news, sbir, funding);

  // Talent block: hold static — EVONA's internal data, not LLM-knowable.
  const talent = (existing && existing.talent) || {
    stat:      "38%",
    statLabel: "Week-over-week growth in resumes from primes to Series B/C",
    head:      "Talent is leaving big-aero — and it's not about money",
    body:      "Compensation is not the gating factor. The complaint, almost universally, is schedule risk — the inability to ship anything quickly, the half-decade gap between joining and seeing flight hardware, the meeting that exists to schedule the meeting. The startups absorbing this talent will, in two years, be hard to compete with on a level playing field.",
    cta:       "EVONA moves people in this market. See open roles →",
    ctaHref:   "#jobs"
  };

  const briefing = {
    updated:  new Date().toISOString().slice(0, 10),
    issue:    nextIssueNumber(existing),
    headline: narrative.headline,
    deck:     narrative.deck,
    stats,
    stories:   narrative.stories,
    watchlist: narrative.watchlist,
    talent,
    tickers:   narrative.tickers,
    footnote:  "Updated daily at 09:00 EDT. SBIR weekly. Stock prices live. Read the raw intel in the terminal →"
  };

  await fs.writeFile(BRIEFING_PATH, JSON.stringify(briefing, null, 2) + "\n");
  console.log(`Wrote ${BRIEFING_PATH} (${briefing.issue})`);
}

main().catch(err => {
  console.warn(`Unexpected error: ${err.message}`);
  process.exit(0);  // never fail the workflow
});
